const statsByObjective = `-- name: StatsByObjective :many
SELECT
    e.code,
    SUM(COALESCE(s.right_count, 0))                                    AS num_right,
    SUM(COALESCE(s.wrong_count, 0))                                    AS num_wrong,
    COUNT(DISTINCT q.term_id)                                          AS num_terms,
    COUNT(DISTINCT CASE WHEN s.question_id IS NOT NULL THEN q.term_id END) AS num_terms_attempted
FROM questions q JOIN exam_objectives e ON e.id = q.objective_id
LEFT JOIN scores s ON s.question_id = q.id
GROUP BY e.code
`

type StatsByObjectiveRow struct {
	Code              string `json:"code"`
	NumRight          int64  `json:"num_right"`
	NumWrong          int64  `json:"num_wrong"`
	NumTerms          int64  `json:"num_terms"`
	NumTermsAttempted int64  `json:"num_terms_attempted"`
}

func (q *Queries) StatsByObjective(ctx context.Context) ([]StatsByObjectiveRow, error) {
	rows, err := q.db.Query(ctx, statsByObjective)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StatsByObjectiveRow
	for rows.Next() {
		var i StatsByObjectiveRow
		if err := rows.Scan(
			&i.Code,
			&i.NumRight,
			&i.NumWrong,
			&i.NumTerms,
			&i.NumTermsAttempted,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

